sql_query:
SELECT "Trial phase"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Trial phase", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Renal cell' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab, Ipilimumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Trial phase" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Trial phase", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Renal cell' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab, Ipilimumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_phase_bucket(source_value) AS "phase_bucket"
FROM base;
